"""Adjudicate semantic formatting separately and publish the evidence scorecard."""
import json
from pathlib import Path
from receptionist import parse_time
from summarize_readiness import stats
ROOT=Path(__file__).parent
OUT=ROOT/'results/readiness-evaluation'
def main():
 h=json.loads((OUT/'heldout.json').read_text());e=json.loads((OUT/'evidence.json').read_text());p=json.loads((OUT/'public.json').read_text())
 adjudicated=[]
 for row in h['cases']:
  checks=dict(row['checks'])
  if 'time' in row['expected']:
   got=parse_time(row['decision']['fields'].get('time') or '')
   checks['time']=any(got==parse_time(want) for want in row['expected']['time'])
  # An instruction attack containing a reservation request has no unique scope
  # gold. Assess its no-write behavior separately; never count it as a model fail.
  adjudicated.append({'id':row['id'],'checks':checks,'scored':row['id']!='prompt_injection','passed':all(checks.values()),'note':'Canonicalized clock format; extra unstated fields are audited separately.'})
 scored=[r for r in adjudicated if r['scored']]
 metric=lambda key:{'correct':sum(r['checks'][key] for r in scored if key in r['checks']),'total':sum(key in r['checks'] for r in scored)}
 score={'readiness':'Supervised prototype; not ready for unattended customer voice service','no_overall_numeric_score':'The sampling is curated and small; a blended percentage would conceal critical coverage gaps.','baseline':e['baseline'],'baseline_legacy_order_sha256':e['baseline_legacy_order_sha256'],'baseline_matches_archived':e['baseline_matches_archived'],'baseline_unchanged_in_new_probes':h['baseline_unchanged'] and p['baseline_unchanged'],'heldout':{'sample_size':len(scored),'selected_expectations_passed':sum(r['passed'] for r in scored),'relevance':metric('relevance'),'intent':metric('intent'),'latency_ms':stats([r['elapsed_ms'] for r in h['cases']]),'adjudication':adjudicated,'context_field_leakage':{'observed_cases':['booking_negation','correction_two_fields','time_quarter_to','unclear_in_context','name_context','phone_words'],'note':'Direct semantic probes bypass public fast paths; these are not cross-session leaks or demonstrated writes.'},'warning':'Selected checks omit many field domains. Not end-to-end completion or population accuracy.'},'generated_audio':{'original_group_completion':{'passed':11,'total':12,'note':'12 API/audio scenario groups; excludes 2 deterministic groups; includes scripted caller repair.'},'original_strict_no_repair_group_completion_upper_bound':{'passed_at_most':10,'total':12,'note':'One phone failure plus separate confirmation repeat. Curated deliberate corrections are not counted as accidental repair.'},'recovery_verified_groups':{'passed':12,'total':12,'note':'11 original group passes plus targeted phone rerun; different synthetic phone, not same-caller recovery proof.'},'original_phone_exact':{'correct':13,'total':14,'note':'Original full run phone digit-word turns; excludes deliberately incomplete inputs.'},'selected_phone_exact':{'correct':14,'total':14,'note':'13 original successful attempts plus targeted replacement run.'},'all_phone_attempts_including_failed_parent':{'correct':14,'total':15},'same_caller_phone_recovery_rate':None,'confirmation_repair_observed':1},'verification':{'new_contract_and_database_tests_passed':29,'prior_tests_passed':283,'prior_subtests_passed':11,'note':'Most prior routing/workflow mocks force legacy. New unified contracts mock model responses; held-out probes use actual model.'},'latency':{'synthetic_audio':e['synthetic_turn_latency'],'api_and_decision':e['audit_stages'],'generation_calls':e['audit_llm_calls'],'model_load_ms':e['audit_model_load_ms'],'current_end_of_speech_to_first_audio_ms':None,'current_vad_ms':None,'current_tts_first_audio_ms':None,'cold_start':None,'throughput_under_load':None},'limitations':['Single laptop, curated prompts, one model sample per held-out case; p95 from 16 is essentially the largest observation.','No saved human audio or physical microphone/speaker tests; no accent/noise/echo validation.','No new full generated-audio suite was run; archived reports and audits are distinguished from fresh text probes.','Two historical voice_metrics rows match no selected session; exclude from current latency score.','No measured current policy-answer factuality rate; retrieval recall is not answer correctness.','Original sandbox transport denial was archived, excluded from model accuracy, and rerun with localhost access.','Initial public phone probe used an invalid empty mock response; excluded and superseded by public.json and guards.json.','An initial sandbox TestClient run stalled and was interrupted; approved isolated rerun passed.','No new shared API processes, production behavior, models or UX were changed.'], 'priorities':[{'priority':1,'issue':'Decision generation latency','evidence':'25 suite generations: median 9.29s, p95 10.91s. Fixed corpus booking worsened 3.61s to 11.05s.'},{'priority':1,'issue':'Held-out policy routing and availability narrowing','evidence':'Late-train policy and anything free in November both request phone; two neighboring availability phrasings narrow correctly.'},{'priority':1,'issue':'Speech first-attempt robustness','evidence':'Original phone exact 13/14; extra digits rejected. One yes please transcript gained said, requiring a repeat before cancellation.'},{'priority':2,'issue':'Semantic field fidelity','evidence':'Unstated context fields copied in 6 probes; direct model phone had an extra digit. Deterministic public phone/time guards passed.'},{'priority':2,'issue':'Evaluation and observability gaps','evidence':'No matched current first-audio/VAD metrics, human audio, cold-start or sustained load sample. Cleanup error can mask ASR assertion failure.'}]}
 (OUT/'scorecard.json').write_text(json.dumps(score,indent=2),encoding='utf-8')
 print(json.dumps({'selected_checks':score['heldout']['selected_expectations_passed'],'n':len(scored),'relevance':metric('relevance'),'intent':metric('intent'),'heldout_latency':score['heldout']['latency_ms'],'tools':e['audit_stages']['tool_spans_ms']},indent=2))
if __name__=='__main__':main()
